//! Cross-asset covariance and portfolio diagnostics. No sizing or order execution.
use serde::{Deserialize,Serialize};
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq)]pub struct PortfolioMetrics{pub expected_return_per_period:f64,pub volatility_per_period:f64,pub value_at_risk:f64,pub expected_shortfall:f64,pub maximum_drawdown:f64,pub concentration_hhi:f64,pub diversification_ratio:f64}
fn valid_weights(w:&[f64])->bool{!w.is_empty()&&w.iter().all(|x|x.is_finite()&&*x>=0.0)&&(w.iter().sum::<f64>()-1.0).abs()<1e-6}
pub fn calculate_portfolio_returns(rows:&[Vec<f64>],weights:&[f64])->Option<Vec<f64>>{if !valid_weights(weights)||rows.is_empty()||rows.iter().any(|r|r.len()!=weights.len()||r.iter().any(|v|!v.is_finite()||*v<=-1.0)){return None}Some(rows.iter().map(|r|r.iter().zip(weights).map(|(v,w)|v*w).sum()).collect())}
pub fn calculate_covariance_matrix(rows:&[Vec<f64>])->Option<Vec<Vec<f64>>>{if rows.len()<2||rows[0].is_empty(){return None}let n=rows[0].len();if rows.iter().any(|r|r.len()!=n||r.iter().any(|v|!v.is_finite())){return None}let m:Vec<f64>=(0..n).map(|i|rows.iter().map(|r|r[i]).sum::<f64>()/rows.len()as f64).collect();Some((0..n).map(|i|(0..n).map(|j|rows.iter().map(|r|(r[i]-m[i])*(r[j]-m[j])).sum::<f64>()/(rows.len()-1)as f64).collect()).collect())}
pub fn calculate_correlation_matrix(cov:&[Vec<f64>])->Option<Vec<Vec<f64>>>{let n=cov.len();if n==0||cov.iter().any(|r|r.len()!=n||r.iter().any(|v|!v.is_finite()))||(0..n).any(|i|cov[i][i]<0.0){return None}Some((0..n).map(|i|(0..n).map(|j|{let d=(cov[i][i]*cov[j][j]).sqrt();if d<=f64::EPSILON{if i==j{1.0}else{0.0}}else{(cov[i][j]/d).clamp(-1.0,1.0)}}).collect()).collect())}
pub fn calculate_portfolio_metrics(rows:&[Vec<f64>],weights:&[f64],alpha:f64)->Option<PortfolioMetrics>{if !alpha.is_finite()||!(0.0..0.5).contains(&alpha){return None}let r=calculate_portfolio_returns(rows,weights)?;if r.len()<2{return None}let mean=r.iter().sum::<f64>()/r.len()as f64;let var=r.iter().map(|v|(v-mean).powi(2)).sum::<f64>()/(r.len()-1)as f64;let mut sorted=r.clone();sorted.sort_by(f64::total_cmp);let q=((sorted.len()-1)as f64*alpha).floor()as usize;let value_at_risk=sorted[q];let tail:Vec<f64>=sorted.iter().copied().filter(|v|*v<=value_at_risk).collect();let expected_shortfall=tail.iter().sum::<f64>()/tail.len()as f64;let(mut equity,mut peak,mut drawdown)=(1.0_f64,1.0_f64,0.0_f64);for v in &r{equity*=1.0+v;peak=peak.max(equity);if peak>0.0{drawdown=drawdown.max((peak-equity)/peak)}}let cov=calculate_covariance_matrix(rows)?;let pv=(0..weights.len()).map(|i|(0..weights.len()).map(|j|weights[i]*weights[j]*cov[i][j]).sum::<f64>()).sum::<f64>();let weighted_vol=(0..weights.len()).map(|i|weights[i]*cov[i][i].max(0.0).sqrt()).sum::<f64>();Some(PortfolioMetrics{expected_return_per_period:mean,volatility_per_period:var.sqrt(),value_at_risk,expected_shortfall,maximum_drawdown:drawdown,concentration_hhi:weights.iter().map(|w|w*w).sum(),diversification_ratio:if pv>f64::EPSILON{weighted_vol/pv.sqrt()}else{0.0}})}
#[cfg(test)]mod tests{use super::*;#[test]fn correlation_tracks_aligned_assets(){let r=vec![vec![0.01,0.02],vec![0.02,0.04],vec![-0.01,-0.02],vec![0.0,0.0]];let c=calculate_correlation_matrix(&calculate_covariance_matrix(&r).unwrap()).unwrap();assert!(c[0][1]>0.99)}#[test]fn metrics_include_tail_and_concentration(){let r=vec![vec![0.01,0.0],vec![0.02,0.01],vec![-0.03,-0.01],vec![0.01,0.0],vec![-0.02,-0.01]];let m=calculate_portfolio_metrics(&r,&[0.5,0.5],0.2).unwrap();assert!(m.volatility_per_period>0.0);assert!((m.concentration_hhi-0.5).abs()<1e-9)}#[test]fn malformed_alignment_is_rejected(){assert!(calculate_portfolio_returns(&[vec![0.1]],&[0.5,0.5]).is_none())}}